import { test } from 'node:test';
import assert from 'node:assert/strict';
import { paginar } from './solution.mjs';

test('página do meio devolve os itens certos com links de navegação', () => {
  const pagina = paginar(['a', 'b', 'c', 'd', 'e'], 2, 2);
  assert.deepEqual(pagina.itens, ['c', 'd']);
  assert.equal(pagina.total, 5);
  assert.equal(pagina.totalPaginas, 3);
  assert.equal(pagina.anterior, 1);
  assert.equal(pagina.proxima, 3);
});

test('primeira página não tem anterior; última não tem próxima', () => {
  const primeira = paginar(['a', 'b', 'c', 'd', 'e'], 1, 2);
  assert.equal(primeira.anterior, null);
  assert.equal(primeira.proxima, 2);

  const ultima = paginar(['a', 'b', 'c', 'd', 'e'], 3, 2);
  assert.equal(ultima.anterior, 2);
  assert.equal(ultima.proxima, null);
});

test('lista vazia devolve página vazia com totalPaginas 1', () => {
  const pagina = paginar([], 1, 2);
  assert.deepEqual(pagina.itens, []);
  assert.equal(pagina.total, 0);
  assert.equal(pagina.totalPaginas, 1);
  assert.equal(pagina.anterior, null);
  assert.equal(pagina.proxima, null);
});

test('página ou tamanho inválidos lançam erro', () => {
  assert.throws(() => paginar(['a'], 0, 2), /paginação inválida/);
  assert.throws(() => paginar(['a'], 1.5, 2), /paginação inválida/);
  assert.throws(() => paginar(['a'], 1, '2'), /paginação inválida/);
});

solutionCode:
export function paginar(lista, pagina, itensPorPagina) {
  if (!Number.isInteger(pagina) || pagina < 1 || !Number.isInteger(itensPorPagina) || itensPorPagina < 1) {
    throw new Error('paginação inválida');
  }

  const total = lista.length;

  // total de páginas: quantas fatias de itensPorPagina cobrem a lista
  let totalPaginas = 0;
  for (let i = 0; i < total; i = i + itensPorPagina) {
    totalPaginas += 1;
  }
  if (totalPaginas === 0) {
    totalPaginas = 1; // lista vazia ainda tem uma página (vazia)
  }

  const inicio = (pagina - 1) * itensPorPagina;

  return {
    itens: lista.slice(inicio, inicio + itensPorPagina),
    total,
    pagina,
    itensPorPagina,
    totalPaginas,
    anterior: pagina > 1 ? pagina - 1 : null,
    proxima: pagina < totalPaginas ? pagina + 1 : null,
  };
}
